#include <functional>
#include <stdexcept>
#include <string>

std::string outcome(const std::function<void()>& action)
{
    try
    {
        action();
        return "ok";
    }
    catch (const std::out_of_range& e)
    {
        return std::string{ "out of range: " } + e.what();
    }
    catch (const std::logic_error& e)
    {
        return std::string{ "logic error: " } + e.what();
    }
    catch (const std::exception& e)
    {
        return std::string{ "error: " } + e.what();
    }
    catch (...)
    {
        return "unknown";
    }
}

std::string retried(const std::function<void()>& action, int attempts)
{
    for (int i{ 1 }; i <= attempts; ++i)
    {
        try
        {
            action();
            return "ok after " + std::to_string(i);
        }
        catch (...)
        {
        }
    }
    return "gave up";
}

unitTests:
TEST("ok") { CHECK_EQ(outcome([] {}), "ok"); }
TEST("most specific first") { CHECK_EQ(outcome([] { std::vector<int> v; (void)v.at(3); }).substr(0, 14), "out of range: "); CHECK_EQ(outcome([] { throw std::out_of_range{ "x" }; }), "out of range: x"); }
TEST("other logic errors") { CHECK_EQ(outcome([] { throw std::invalid_argument{ "bad" }; }), "logic error: bad"); }
TEST("other standard exceptions") { CHECK_EQ(outcome([] { throw std::runtime_error{ "boom" }; }), "error: boom"); }
TEST("non-standard throws") { CHECK_EQ(outcome([] { throw 42; }), "unknown"); }
TEST("retried succeeds once the action stops failing") { int calls{ 0 }; CHECK_EQ(retried([&] { if (++calls < 3) throw std::runtime_error{ "not yet" }; }, 5), "ok after 3"); CHECK_EQ(calls, 3); }
TEST("retried gives up") { int calls{ 0 }; CHECK_EQ(retried([&] { ++calls; throw 1; }, 4), "gave up"); CHECK_EQ(calls, 4); CHECK_EQ(retried([] {}, 0), "gave up"); }

